/*
 * AEra Agents — runtime pairing ("enrollment") for the dashboard.
 *
 * SECURITY MODEL
 * --------------
 * The Ed25519 agent key is generated by the Agent Runtime on the owner's
 * machine. This file never creates, receives, displays or stores key material:
 *
 *   dashboard                          Agent Runtime
 *   ---------                          -------------
 *   create enrollment (session) ──►    code (shown here once)
 *                                      `python -m agent_runtime enroll <code>`
 *                                      generates key locally, submits PUBLIC
 *                                      key + proof of possession
 *   shows key fingerprint       ◄──    prints the same fingerprint
 *   owner compares, signs the EXISTING owner challenge with the wallet
 *   complete ──────────────────►       runtime receives agent_id / key_id
 *
 *   - The enrollment code lives only in this closure's memory. It is never
 *     written to browser storage, cookies, the URL or the console, and it is
 *     dropped as soon as the pairing ends.
 *   - Status checks go ONLY to the owner-scoped dashboard enrollment endpoint,
 *     stop on any terminal state and stop at expiry.
 *   - Approval reuses AEraAgents' owner-challenge flow; there is no second
 *     signing implementation.
 */
(function () {
    'use strict';

    const DASHBOARD_ENROLL_API = '/api/dashboard/agents/enrollments';
    const AGENTS_ENROLL_API = '/api/agents/enrollments';
    const STATUS_INTERVAL_MS = 3000;

    // The only mutable pairing state. Memory only.
    let current = null;     // { id, code, expiresAt }
    let timer = null;

    function A() { return window.AEraAgents || {}; }
    function esc(v) { return (A()._escapeHtml || String)(v); }

    function token() {
        return (typeof getAuthToken === 'function') ? getAuthToken() : null;
    }

    async function apiJson(url, options) {
        const res = await fetch(url, options);
        let body = null;
        try { body = await res.json(); } catch (e) { /* non-JSON */ }
        return { ok: res.ok, status: res.status, body: body };
    }

    function errorOf(res) {
        if (res.body && res.body.error) return res.body.error;
        return A()._agentErrorOf ? A()._agentErrorOf(res) : 'http_' + res.status;
    }

    function panel() { return document.getElementById('agentEnrollPanel'); }

    function setStatus(msg, kind) {
        const el = document.getElementById('agentEnrollStatus');
        if (!el) return;
        const colour = kind === 'error' ? '#ef4444'
            : kind === 'ok' ? 'var(--success)' : 'rgba(240,244,255,.7)';
        el.innerHTML = '<span style="color:' + colour + ';">' + esc(msg) + '</span>';
    }

    function stopChecking() {
        if (timer) { clearTimeout(timer); timer = null; }
    }

    function reset() {
        stopChecking();
        current = null;
        const p = panel();
        if (p) { p.innerHTML = ''; p.style.display = 'none'; }
    }

    function selectedCapabilities() {
        return Array.prototype.slice
            .call(document.querySelectorAll('.agent-register-cap:checked'))
            .map(cb => cb.value);
    }

    // ------------------------------------------------------------- step 1

    async function start() {
        const nameEl = document.getElementById('registerAgentName');
        const label = nameEl ? nameEl.value.trim() : '';
        const t = token();
        const p = panel();
        if (!p) return;
        p.style.display = 'block';
        if (!t) { p.innerHTML = statusBox(); setStatus('❌ Connect your wallet first.', 'error'); return; }
        if (label.length < 3) {
            p.innerHTML = statusBox();
            setStatus('❌ Agent name must be at least 3 characters.', 'error');
            return;
        }
        if (current) await cancel(true);

        p.innerHTML = statusBox();
        setStatus('⏳ Creating a pairing code…');
        const caps = selectedCapabilities();
        const res = await apiJson(DASHBOARD_ENROLL_API, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + t },
            body: JSON.stringify({ label: label, capabilities: caps.length ? caps : null })
        });
        if (!res.ok || !res.body || !res.body.success) {
            setStatus('❌ Could not start pairing: ' + errorOf(res), 'error');
            return;
        }
        const e = res.body.enrollment;
        current = { id: e.enrollment_id, code: e.enrollment_code, expiresAt: e.expires_at };
        renderWaitingForRuntime(e);
        scheduleCheck();
    }

    function statusBox() {
        return '<div id="agentEnrollStatus" style="font-size:12px;margin-top:8px;"></div>';
    }

    function commandText() {
        return 'python -m agent_runtime enroll ' + current.code;
    }

    function renderWaitingForRuntime(e) {
        const p = panel();
        if (!p || !current) return;
        p.innerHTML = '' +
            '<h5 style="margin:0 0 8px;font-size:13px;color:var(--secondary);">' +
                'Step 2 of 3 — connect your Agent Runtime</h5>' +
            '<p style="font-size:12px;margin:0 0 8px;color:rgba(240,244,255,.8);line-height:1.6;">' +
                'Run this on the machine where the Agent should live. The runtime creates the ' +
                'Agent\'s key <strong>there</strong> — it never comes to this page or to AEra.</p>' +
            '<pre id="agentEnrollCommand" style="margin:0;padding:10px;background:rgba(5,8,20,.8);' +
                'border-radius:6px;font-size:11px;color:var(--secondary);white-space:pre-wrap;' +
                'word-break:break-all;">' + esc(commandText()) + '</pre>' +
            '<div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:8px;">' +
                '<button type="button" class="cta-button cta-secondary-small" ' +
                    'onclick="AEraAgentEnroll.copyCommand()" style="padding:5px 10px;font-size:11px;">' +
                    '📋 Copy command</button>' +
                '<button type="button" class="cta-button cta-secondary-small" ' +
                    'onclick="AEraAgentEnroll.cancel()" style="padding:5px 10px;font-size:11px;' +
                    'background:rgba(239,68,68,.15);border:1px solid #ef4444;color:#ef4444;">' +
                    'Cancel</button>' +
            '</div>' +
            '<p style="font-size:11px;opacity:.65;margin:8px 0 0;line-height:1.6;">' +
                'The code is single-use and expires at ' + esc(new Date(e.expires_at).toLocaleTimeString()) +
                '. Treat it like a one-time password. The runtime ships in the AEra source tree ' +
                '(<code>agent_runtime/</code>); set <code>AERA_BASE_URL</code> to this AEra instance and, ' +
                'recommended, <code>AERA_RUNTIME_KEY_PASSPHRASE</code> to encrypt the key at rest.</p>' +
            statusBox();
        setStatus('⏳ Waiting for your runtime…');
    }

    function renderApprove(view) {
        const p = panel();
        if (!p || !current) return;
        p.innerHTML = '' +
            '<h5 style="margin:0 0 8px;font-size:13px;color:var(--secondary);">' +
                'Step 3 of 3 — confirm and approve</h5>' +
            '<p style="font-size:12px;margin:0 0 6px;color:rgba(240,244,255,.8);">' +
                'Your runtime submitted a key with this fingerprint:</p>' +
            '<div id="agentEnrollFingerprint" style="font-family:monospace;font-size:16px;' +
                'letter-spacing:1px;padding:10px;background:rgba(5,8,20,.8);border-radius:6px;' +
                'color:var(--success);text-align:center;">' + esc(view.key_fingerprint) + '</div>' +
            '<p style="font-size:11px;color:#f59e0b;margin:8px 0;line-height:1.6;">' +
                '⚠️ Approve <strong>only</strong> if this matches the fingerprint printed by your ' +
                'runtime. If it does not match, someone else used your code — cancel.</p>' +
            '<div style="display:flex;gap:8px;flex-wrap:wrap;">' +
                '<button type="button" class="cta-button" onclick="AEraAgentEnroll.approve()" ' +
                    'style="flex:1;padding:8px;font-size:12px;">✍️ Fingerprint matches — sign &amp; create Agent</button>' +
                '<button type="button" class="cta-button cta-secondary-small" ' +
                    'onclick="AEraAgentEnroll.cancel()" style="padding:8px 12px;font-size:11px;' +
                    'background:rgba(239,68,68,.15);border:1px solid #ef4444;color:#ef4444;">' +
                    'Does not match — cancel</button>' +
            '</div>' +
            statusBox();
    }

    // ------------------------------------------------------ status checks

    function scheduleCheck() {
        stopChecking();
        timer = setTimeout(checkStatus, STATUS_INTERVAL_MS);
    }

    async function checkStatus() {
        timer = null;
        if (!current) return;
        const t = token();
        if (!t) { setStatus('❌ Session ended. Reconnect your wallet.', 'error'); return; }
        let res;
        try {
            res = await apiJson(DASHBOARD_ENROLL_API + '/' + encodeURIComponent(current.id), {
                headers: { 'Authorization': 'Bearer ' + t }
            });
        } catch (e) {
            scheduleCheck();
            return;
        }
        if (!current) return;
        if (!res.ok || !res.body || !res.body.success) {
            setStatus('❌ ' + errorOf(res), 'error');
            return;
        }
        const view = res.body.enrollment;
        if (view.status === 'pending') { scheduleCheck(); return; }
        if (view.status === 'key_submitted') { renderApprove(view); return; }
        if (view.status === 'expired') {
            current = null;
            setStatus('⌛ The pairing code expired. Start again.', 'error');
            return;
        }
        if (view.status === 'completed') { finished(view.agent_id); return; }
        current = null;
        setStatus('Pairing ' + view.status + '.', 'error');
    }

    // ------------------------------------------------------------ approve

    async function approve() {
        if (!current || !A()._authorizeOwnerOperation) return;
        const id = current.id;
        try {
            setStatus('⏳ Waiting for your wallet signature…');
            // Owner challenge bound to THIS enrollment (agent_id "enrollment:<id>").
            const auth = await A()._authorizeOwnerOperation('register', 'enrollment:' + id);
            setStatus('⏳ Creating Agent…');
            const res = await apiJson(AGENTS_ENROLL_API + '/' + encodeURIComponent(id) + '/complete', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(auth)
            });
            if (!res.ok) { setStatus('❌ Approval failed: ' + errorOf(res), 'error'); return; }
            finished(res.body.agent_id);
        } catch (e) {
            setStatus('❌ ' + (e && e.message ? e.message : 'approval_failed'), 'error');
        }
    }

    function finished(agentId) {
        stopChecking();
        current = null;
        const p = panel();
        if (p) {
            p.innerHTML = '<p style="font-size:12px;color:var(--success);margin:0;line-height:1.6;">' +
                '✅ Agent created: <code>' + esc(agentId || '') + '</code><br>' +
                '<span style="color:rgba(240,244,255,.75);">Your runtime picks up its identity ' +
                'automatically. Start it with <code>python -m agent_runtime run</code>.</span></p>';
        }
        const nameEl = document.getElementById('registerAgentName');
        if (nameEl) nameEl.value = '';
        if (A().load) A().load();
    }

    // ------------------------------------------------------------- cancel

    async function cancel(silent) {
        if (!current) { reset(); return; }
        const id = current.id;
        const t = token();
        stopChecking();
        current = null;
        if (t) {
            try {
                await apiJson(DASHBOARD_ENROLL_API + '/' + encodeURIComponent(id), {
                    method: 'DELETE', headers: { 'Authorization': 'Bearer ' + t }
                });
            } catch (e) { /* expiry cleans up anyway */ }
        }
        if (silent === true) return;
        reset();
        if (A()._toast) A()._toast('Pairing cancelled');
    }

    function copyCommand() {
        if (!current) return;
        navigator.clipboard.writeText(commandText()).then(
            () => A()._toast && A()._toast('📋 Command copied'),
            () => A()._toast && A()._toast('❌ Could not copy', true)
        );
    }

    window.AEraAgentEnroll = {
        start: start,
        approve: approve,
        cancel: cancel,
        copyCommand: copyCommand
    };
})();
